INSERT INTO sea_pack.`blog_article` VALUES (2, '自动封装统一响应接口', '', '## 一、基础封装类设计\n\n创建一个泛型响应类，包含 `<font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\">code</font>`（状态码）、`<font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\">data</font>`（业务数据）、`<font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\">msg</font>`（消息）三个字段。\n\n```java\npackage org.seapack.config;\n\nimport lombok.AllArgsConstructor;\nimport lombok.Data;\nimport lombok.NoArgsConstructor;\n\n@Data\n@NoArgsConstructor\n@AllArgsConstructor\npublic class Result<T> {\n    private int code; // 状态码，如200成功、500错误\n    private String msg;  // 业务数据，泛型支持任意类型\n    private T data;  // 提示信息，如\"操作成功\"\n\n    //成功响应（无数据）\n    public static <T> Result<T> success() {\n        return new Result<>(200, \"成功\", null);\n    }\n\n    // 成功响应（带数据）\n    public static <T> Result<T> success(T data) {\n        return new Result<>(200, \"成功\", data);\n    }\n\n    // 失败响应（自定义消息）\n    public static <T> Result<T> error(String msg){\n        return new Result<>(500, msg, null);\n    }\n\n    // 失败响应 （自定义状态码 + 消息）\n    public static <T> Result<T> error(int code, String msg){\n        return new Result<>(code, msg, null);\n    }\n}\n```\n\n其中的关键点在于：使用静态工厂方法，避免手动构造对象，简化代码。使用泛型\n\n**注解说明**：\n\n:::info  \n@Data 注解是Lombok 提供的复合注解，会自动生成以下方法：\n\n*   所有字段的 getter 方法（如 getCode()）\n*   所有非 final 字段的 setter 方法（如 setMsg(String msg)）\n*   toString() 方法（打印对象属性值）\n*   equals() 和 hashCode() 方法（基于对象属性比较相等性）\n\n:::\n\n:::info  \n@NoArgsConstructor 注解可以\\*\\*自动生成无参构造函数\\*\\*\n\n:::\n\n:::info  \n@AllArgsConstructor 注解可以\\*\\*自动生成全参构造函数\\*\\*，**参数顺序与类中字段声明顺序一致**\n\n:::\n\n三者同时使用时可以自动生成完整的POJO结构。\n\n**注解组合**\n\n**整体效果**\n\n**应用优势**\n\n`<font style=\"color:rgba(0, 0, 0, 0.9);\">@Data</font>` + `<font style=\"color:rgba(0, 0, 0, 0.9);\">@NoArgsConstructor</font>` + `<font style=\"color:rgba(0, 0, 0, 0.9);\">@AllArgsConstructor</font>`\n\n自动生成完整的 POJO 结构（getter/setter/构造方法/对象方法）\n\n**减少 80% 样板代码**，提升开发效率\n\n静态工厂方法（如 `<font style=\"color:rgba(0, 0, 0, 0.9);\">success()</font>`）\n\n复用全参构造，提供语义化对象创建入口\n\n**统一响应格式**：前端只需处理固定结构（`<font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\">{code, msg, data}</font>`）\n\n## 二、状态码标准化\n\n通过枚举统一管理状态码，避免“魔法数字”\n\n```java\npackage org.seapack.config;\n\npublic enum ResultCode {\n    SUCCESS(200, \"操作成功\"),\n    BAD_REQUEST(400, \"参数错误\"),\n    UNAUTHORIZED(401, \"未授权\"),\n    INTERNAL_ERROR(500, \"系统异常\");\n\n    private final int code;\n    private final String msg;\n\n    ResultCode(int code, String msg) {\n        this.code = code;\n        this.msg = msg;\n    }\n}\n\n```\n\n使用示例如下：\n\n```java\nResult.success().setCode(ResultCode.SUCCESS.getCode());\n```\n\n## 三、自动封装策略\n\n通过 `<font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\">@ResponseBodyAdvice</font>` 拦截Controller返回值，自动包装为统一格式。\n\n```java\npackage org.seapack.config;\n\nimport org.springframework.core.MethodParameter;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.server.ServerHttpRequest;\nimport org.springframework.http.server.ServerHttpResponse;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\nimport org.springframework.web.servlet.mvc.method.annotation.ResponseBodyAdvice;\nimport com.alibaba.fastjson.JSON;\n\n@RestControllerAdvice\npublic class GlobalResponseHandler implements ResponseBodyAdvice<Object> {\n\n    /**\n     * 若返回值类型已是 Result 类（如手动返回 Result.success()），则跳过处理（return false），\n     * 避免重复包装, 若其他类型（如 String、User 等）返回 true，进入 beforeBodyWrite() 处理\n     *\n     * @param returnType 控制器方法的返回值类型（含泛型信息）\n     * @param converterType 当前选定的消息转换器（如 MappingJackson2HttpMessageConverter）\n     * @return 返回true或false ,true继续向下执行beforeBodyWrite方法，false就此结束\n     */\n    @Override\n    public boolean supports(MethodParameter returnType, Class converterType) {\n        return !returnType.getParameterType().isAssignableFrom(Result.class);\n    }\n\n    /**\n     * 统一封装响应体\n     * @param body  控制器方法的原始返回值（未封装）\n     * @param returnType 控制器方法的返回值类型（含泛型信息）\n     * @param mediaType 当前响应的媒体类型（如 application/json）\n     * @param converterType 当前选定的消息转换器\n     * @param request HTTP 请求对象，可用于修改头信息\n     * @param response HTTP 响应对象，可用于修改状态码\n     * @return\n     */\n    @Override\n    public Object beforeBodyWrite(Object body, MethodParameter returnType,\n                                  MediaType mediaType, Class converterType,\n                                  ServerHttpRequest request, ServerHttpResponse response) {\n\n        // String类型需特殊处理（避免被解析为文本）\n        if (body instanceof String) {\n            return JSON.toJSONString(Result.success(body));\n        }\n        // 其他类型自动封装为Result\n        return Result.success(body);\n    }\n}\n\n```\n\n**注解说明**：\n\n:::info  \n**@RestControllerAdvice** 注解是组合注解（`<font style=\"color:rgba(0, 0, 0, 0.9);\">@ControllerAdvice</font>` + `<font style=\"color:rgba(0, 0, 0, 0.9);\">@ResponseBody</font>`），用于**全局拦截控制器返回值**，实现统一响应封装。\n\n其主要特性有：\n\n*   自动将返回值序列化为 JSON（无需额外 `<font style=\"color:rgba(0, 0, 0, 0.9);\">@ResponseBody</font>`）\n*   可限定作用范围（如 `<font style=\"color:rgba(0, 0, 0, 0.9);\">basePackages</font>` 指定包路径）\n\n:::\n\n:::info  \n\\*\\*@Override \\*\\*是 Java 中的一种元注解（Annotation），主要用于方法覆盖（重写）的场景，其核心作用是通过编译器校验确保方法正确覆盖父类或接口中的方法，同时提升代码可读性和可维护性。\n\n当方法添加 @Override 注解后，编译器会严格检查该方法是否与父类或接口中的目标方法签名一致（包括方法名、参数列表、返回类型）。若不一致（如拼写错误、参数不匹配），编译器会直接报错。\n\n:::\n\n  \n\n  \n\n注意：\n\n1.  需排除 `<font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\">Result</font>` 自身、文件下载等无需封装的接口\n2.  添以下是针对`Result<T>`类中注解及其作用的详细分析，结合 Lombok 框架特性和项目实际应用场景进行说明：\n\n## 四、全局异常处理\n\n使用 `<font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\">@ControllerAdvice</font>` 捕获异常，返回统一错误格式。\n\n```java\npackage org.seapack.config;\n\nimport org.springframework.web.bind.MethodArgumentNotValidException;\nimport org.springframework.web.bind.annotation.ControllerAdvice;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.ResponseBody;\n\n@ControllerAdvice\npublic class GlobalExceptionHandler {\n\n    /**\n     * 处理业务异常\n     * @param e 异常类型\n     * @return\n     */\n    @ExceptionHandler(BusinessException.class) // 指定捕获的异常类型\n    @ResponseBody // 返回JSON格式数据\n    public Result<Void> handleBusinessException(BusinessException e) {\n        return Result.error(e.getCode(), e.getMessage());\n    }\n\n\n    /**\n     * 处理系统异常（如空指针）\n     * @param e 异常类型\n     * @return\n     */\n    @ExceptionHandler(Exception.class)  // 捕获所有未处理的异常\n    @ResponseBody\n    public Result<Void> handleException(Exception e) {\n        //log.error(\"系统异常:\", e);\n        // 返回模糊错误信息\n        return Result.error(500, \"服务繁忙，请重试\");\n    }\n\n    /**\n     * 处理常见异常处理\n     * @param e\n     * @return\n     */\n    @ExceptionHandler(MethodArgumentNotValidException.class)\n    public Result<Void> handleValidationException(MethodArgumentNotValidException e) {\n        String errorMsg = e.getBindingResult().getFieldError().getDefaultMessage();\n        return Result.error(400, errorMsg); // 返回校验失败详情\n    }\n}\n\n\n```\n\n**注解说明**：\n\n:::info  \n@ControllerAdvice 注解可以标记该类为**全局异常处理器**，可捕获所有 @Controller 或 @RestController 抛出的异常。\n\n关键特新如下：\n\n*   集中管理异常处理逻辑，避免重复代码\n*   与 @ExceptionHandler 配合实现异常类型精准匹配\n*   默认作用范围为所有控制器，可通过参数限定（如 basePackages）\n\n:::\n\n:::info  \n@ExceptionHandler 注解捕获并处理控制器方法抛出的异常，实现异常处理逻辑的集中管理\n\n关键特性如下：\n\n1.  异常类型匹配：\n\n*   通过 @ExceptionHandler(异常类型.class) 指定处理的异常类型（如 NullPointerException.class）\n*   支持多异常类型：@ExceptionHandler({Exception1.class, Exception2.class})\n\n1.  作用范围：\n\n*   局部处理：在单个 @Controller 类内定义，仅处理该类抛出的异常\n*   全局处理：结合 @ControllerAdvice 或 @RestControllerAdvice，处理所有控制器的异常\n\n1.  返回值灵活性：\n\n*   可返回 String（视图名称）、ModelAndView、ResponseEntity 或任何对象（需配合 @ResponseBody）\n\n:::\n\n:::info  \n@ResponseBody 注解将方法的返回值直接写入 HTTP 响应体，跳过视图解析器，适用于 RESTful API。\n\n:::\n\n```java\npackage org.seapack.config;\n\nimport lombok.Getter;\n\npublic class BusinessException extends RuntimeException{\n\n    @Getter\n    private int code; // 错误码（如 \"4001\"）\n    private String message; // 错误描述（如 \"用户不存在\"）\n\n    public void setCode(int code) {\n        this.code = code;\n    }\n\n    @Override\n    public String getMessage() {\n        return message;\n    }\n\n    public void setMessage(String message) {\n        this.message = message;\n    }\n}\n\n```', '<h2>一、基础封装类设计</h2><p><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">创建一个泛型响应类，包含 </span><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\"&gt;code&lt;/font&gt;</code><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">（状态码）、</span><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\"&gt;data&lt;/font&gt;</code><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">（业务数据）、</span><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\"&gt;msg&lt;/font&gt;</code><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">（消息）三个字段。</span></p><pre><code class=\"language-java\">package org.seapack.config;\n\nimport lombok.AllArgsConstructor;\nimport lombok.Data;\nimport lombok.NoArgsConstructor;\n\n@Data\n@NoArgsConstructor\n@AllArgsConstructor\npublic class Result&lt;T&gt; {\n    private int code; // 状态码，如200成功、500错误\n    private String msg;  // 业务数据，泛型支持任意类型\n    private T data;  // 提示信息，如\"操作成功\"\n\n    //成功响应（无数据）\n    public static &lt;T&gt; Result&lt;T&gt; success() {\n        return new Result&lt;&gt;(200, \"成功\", null);\n    }\n\n    // 成功响应（带数据）\n    public static &lt;T&gt; Result&lt;T&gt; success(T data) {\n        return new Result&lt;&gt;(200, \"成功\", data);\n    }\n\n    // 失败响应（自定义消息）\n    public static &lt;T&gt; Result&lt;T&gt; error(String msg){\n        return new Result&lt;&gt;(500, msg, null);\n    }\n\n    // 失败响应 （自定义状态码 + 消息）\n    public static &lt;T&gt; Result&lt;T&gt; error(int code, String msg){\n        return new Result&lt;&gt;(code, msg, null);\n    }\n}\n</code></pre><p>其中的关键点在于：使用静态工厂方法，避免手动构造对象，简化代码。使用泛型</p><p><strong>注解说明</strong>：</p><p>:::info<br>@Data 注解是Lombok 提供的复合注解，会自动生成以下方法：</p><ul><li>所有字段的 getter 方法（如 getCode()）</li><li>所有非 final 字段的 setter 方法（如 setMsg(String msg)）</li><li>toString() 方法（打印对象属性值）</li><li>equals() 和 hashCode() 方法（基于对象属性比较相等性）</li></ul><p>:::</p><p>:::info<br>@NoArgsConstructor 注解可以**<span style=\"color: rgb(223, 42, 63);\">自动生成无参构造函数</span>**</p><p>:::</p><p>:::info<br>@AllArgsConstructor 注解可以**<span style=\"color: rgb(223, 42, 63);\">自动生成全参构造函数</span>**，<strong>参数顺序与类中字段声明顺序一致</strong></p><p>:::</p><p>三者同时使用时可以自动生成完整的POJO结构。</p><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><strong>注解组合</strong></th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><strong>整体效果</strong></th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><strong>应用优势</strong></th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);\"&gt;@Data&lt;/font&gt;</code><span style=\"color: rgba(0, 0, 0, 0.9);\"> + </span><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);\"&gt;@NoArgsConstructor&lt;/font&gt;</code><span style=\"color: rgba(0, 0, 0, 0.9);\"> + </span><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);\"&gt;@AllArgsConstructor&lt;/font&gt;</code></td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">自动生成完整的 POJO 结构（getter/setter/构造方法/对象方法）</span></td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><strong>减少 80% 样板代码</strong><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">，提升开发效率</span></td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">静态工厂方法（如 </span><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);\"&gt;success()&lt;/font&gt;</code><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">）</span></td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">复用全参构造，提供语义化对象创建入口</span></td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><strong>统一响应格式</strong><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">：前端只需处理固定结构（</span><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\"&gt;{code, msg, data}&lt;/font&gt;</code><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">）</span></td></tr></tbody></table><h2>二、状态码标准化</h2><p><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">通过枚举统一管理状态码，避免“魔法数字”</span></p><pre><code class=\"language-java\">package org.seapack.config;\n\npublic enum ResultCode {\n    SUCCESS(200, \"操作成功\"),\n    BAD_REQUEST(400, \"参数错误\"),\n    UNAUTHORIZED(401, \"未授权\"),\n    INTERNAL_ERROR(500, \"系统异常\");\n\n    private final int code;\n    private final String msg;\n\n    ResultCode(int code, String msg) {\n        this.code = code;\n        this.msg = msg;\n    }\n}\n\n</code></pre><p>使用示例如下：</p><pre><code class=\"language-java\">Result.success().setCode(ResultCode.SUCCESS.getCode());\n</code></pre><h2>三、自动封装策略</h2><p><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">通过 </span><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\"&gt;@ResponseBodyAdvice&lt;/font&gt;</code><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\"> 拦截Controller返回值，自动包装为统一格式。</span></p><pre><code class=\"language-java\">package org.seapack.config;\n\nimport org.springframework.core.MethodParameter;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.server.ServerHttpRequest;\nimport org.springframework.http.server.ServerHttpResponse;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\nimport org.springframework.web.servlet.mvc.method.annotation.ResponseBodyAdvice;\nimport com.alibaba.fastjson.JSON;\n\n@RestControllerAdvice\npublic class GlobalResponseHandler implements ResponseBodyAdvice&lt;Object&gt; {\n\n    /**\n     * 若返回值类型已是 Result 类（如手动返回 Result.success()），则跳过处理（return false），\n     * 避免重复包装, 若其他类型（如 String、User 等）返回 true，进入 beforeBodyWrite() 处理\n     *\n     * @param returnType 控制器方法的返回值类型（含泛型信息）\n     * @param converterType 当前选定的消息转换器（如 MappingJackson2HttpMessageConverter）\n     * @return 返回true或false ,true继续向下执行beforeBodyWrite方法，false就此结束\n     */\n    @Override\n    public boolean supports(MethodParameter returnType, Class converterType) {\n        return !returnType.getParameterType().isAssignableFrom(Result.class);\n    }\n\n    /**\n     * 统一封装响应体\n     * @param body  控制器方法的原始返回值（未封装）\n     * @param returnType 控制器方法的返回值类型（含泛型信息）\n     * @param mediaType 当前响应的媒体类型（如 application/json）\n     * @param converterType 当前选定的消息转换器\n     * @param request HTTP 请求对象，可用于修改头信息\n     * @param response HTTP 响应对象，可用于修改状态码\n     * @return\n     */\n    @Override\n    public Object beforeBodyWrite(Object body, MethodParameter returnType,\n                                  MediaType mediaType, Class converterType,\n                                  ServerHttpRequest request, ServerHttpResponse response) {\n\n        // String类型需特殊处理（避免被解析为文本）\n        if (body instanceof String) {\n            return JSON.toJSONString(Result.success(body));\n        }\n        // 其他类型自动封装为Result\n        return Result.success(body);\n    }\n}\n\n</code></pre><p><strong>注解说明</strong>：</p><p>:::info<br><strong>@RestControllerAdvice</strong> 注解是组合注解（<code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);\"&gt;@ControllerAdvice&lt;/font&gt;</code><span style=\"color: rgba(0, 0, 0, 0.9);\"> + </span><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);\"&gt;@ResponseBody&lt;/font&gt;</code>），用于<strong>全局拦截控制器返回值</strong>，实现统一响应封装。</p><p>其主要特性有：</p><ul><li><span style=\"color: rgba(0, 0, 0, 0.9);\">自动将返回值序列化为 JSON（无需额外 </span><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);\"&gt;@ResponseBody&lt;/font&gt;</code><span style=\"color: rgba(0, 0, 0, 0.9);\">）</span></li><li><span style=\"color: rgba(0, 0, 0, 0.9);\">可限定作用范围（如 </span><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);\"&gt;basePackages&lt;/font&gt;</code><span style=\"color: rgba(0, 0, 0, 0.9);\"> 指定包路径）</span></li></ul><p>:::</p><p>:::info<br>**<span style=\"color: rgb(223, 42, 63);\">@Override </span>**是 Java 中的一种元注解（Annotation），主要用于方法覆盖（重写）的场景，其核心作用是通过编译器校验确保方法正确覆盖父类或接口中的方法，同时提升代码可读性和可维护性。</p><p>当方法添加 @Override 注解后，编译器会严格检查该方法是否与父类或接口中的目标方法签名一致（包括方法名、参数列表、返回类型）。若不一致（如拼写错误、参数不匹配），编译器会直接报错。</p><p>:::</p><p><br></p><p><br></p><p>注意：</p><ol><li><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">需排除 </span><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\"&gt;Result&lt;/font&gt;</code><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\"> 自身、文件下载等无需封装的接口</span></li><li><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">添</span>以下是针对<code>Result&lt;T&gt;</code>类中注解及其作用的详细分析，结合 Lombok 框架特性和项目实际应用场景进行说明：</li></ol><h2>四、全局异常处理</h2><p><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\">使用 </span><code>&lt;font style=\"color:rgba(0, 0, 0, 0.9);background-color:rgb(252, 252, 252);\"&gt;@ControllerAdvice&lt;/font&gt;</code><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(252, 252, 252);\"> 捕获异常，返回统一错误格式。</span></p><pre><code class=\"language-java\">package org.seapack.config;\n\nimport org.springframework.web.bind.MethodArgumentNotValidException;\nimport org.springframework.web.bind.annotation.ControllerAdvice;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.ResponseBody;\n\n@ControllerAdvice\npublic class GlobalExceptionHandler {\n\n    /**\n     * 处理业务异常\n     * @param e 异常类型\n     * @return\n     */\n    @ExceptionHandler(BusinessException.class) // 指定捕获的异常类型\n    @ResponseBody // 返回JSON格式数据\n    public Result&lt;Void&gt; handleBusinessException(BusinessException e) {\n        return Result.error(e.getCode(), e.getMessage());\n    }\n\n\n    /**\n     * 处理系统异常（如空指针）\n     * @param e 异常类型\n     * @return\n     */\n    @ExceptionHandler(Exception.class)  // 捕获所有未处理的异常\n    @ResponseBody\n    public Result&lt;Void&gt; handleException(Exception e) {\n        //log.error(\"系统异常:\", e);\n        // 返回模糊错误信息\n        return Result.error(500, \"服务繁忙，请重试\");\n    }\n\n    /**\n     * 处理常见异常处理\n     * @param e\n     * @return\n     */\n    @ExceptionHandler(MethodArgumentNotValidException.class)\n    public Result&lt;Void&gt; handleValidationException(MethodArgumentNotValidException e) {\n        String errorMsg = e.getBindingResult().getFieldError().getDefaultMessage();\n        return Result.error(400, errorMsg); // 返回校验失败详情\n    }\n}\n\n\n</code></pre><p><strong>注解说明</strong>：</p><p>:::info<br>@ControllerAdvice 注解可以标记该类为<strong>全局异常处理器</strong>，可捕获所有 @Controller 或 @RestController 抛出的异常。</p><p>关键特新如下：</p><ul><li>集中管理异常处理逻辑，避免重复代码</li><li>与 @ExceptionHandler 配合实现异常类型精准匹配</li><li>默认作用范围为所有控制器，可通过参数限定（如 basePackages）</li></ul><p>:::</p><p>:::info<br>@ExceptionHandler 注解捕获并处理控制器方法抛出的异常，实现异常处理逻辑的集中管理</p><p>关键特性如下：</p><ol><li>异常类型匹配：</li></ol><ul><li>通过 @ExceptionHandler(异常类型.class) 指定处理的异常类型（如 NullPointerException.class）</li><li>支持多异常类型：@ExceptionHandler({Exception1.class, Exception2.class})</li></ul><ol><li>作用范围：</li></ol><ul><li>局部处理：在单个 @Controller 类内定义，仅处理该类抛出的异常</li><li>全局处理：结合 @ControllerAdvice 或 @RestControllerAdvice，处理所有控制器的异常</li></ul><ol><li>返回值灵活性：</li></ol><ul><li>可返回 String（视图名称）、ModelAndView、ResponseEntity 或任何对象（需配合 @ResponseBody）</li></ul><p>:::</p><p>:::info<br>@ResponseBody 注解将方法的返回值直接写入 HTTP 响应体，跳过视图解析器，适用于 RESTful API。</p><p>:::</p><pre><code class=\"language-java\">package org.seapack.config;\n\nimport lombok.Getter;\n\npublic class BusinessException extends RuntimeException{\n\n    @Getter\n    private int code; // 错误码（如 \"4001\"）\n    private String message; // 错误描述（如 \"用户不存在\"）\n\n    public void setCode(int code) {\n        this.code = code;\n    }\n\n    @Override\n    public String getMessage() {\n        return message;\n    }\n\n    public void setMessage(String message) {\n        this.message = message;\n    }\n}\n\n</code></pre><p><br></p>', 'java', 'Java', 'warning', '📝', 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)', 1, 0, 0, 0, 0, '2026-07-01 21:19:05', '2026-07-01 21:19:05');
INSERT INTO sea_pack.`blog_article` VALUES (3, 'GIS基础', '', '官网：[Cesium: The Platform for 3D Geospatial](https://cesium.com/)\n\n中文API文档：[Cesium中文api文档 | Index - Cesium Documentation](http://cesium.xin/cesium/cn/Documentation1.62/index.html)\n\n## 一，Cesium 简介\n\n**Cesium**是AGI公司计算机图形开发小组与2011年研发的三维地球和地图可视化开源JavaScript库，Cesium一词来源于化学元素铯，铯是制造原子钟的关键元素，研发小组通过命名强调Cesium产品精益求精，专注时间数据可视化。\n\nCesium为三维GIS提供了一个高效的数据可视化平台。即：\n\n1.  Cesium是一个跨平台、跨浏览器的**展示三维地球和地图的JavaScript库**\n2.  Cesium使用WebGL来进行硬件加速图形，使用时不需要任何插件支持。\n3.  Cesium是基于Apache2.0许可的开源程序，可以免费用于商业和非商业用途。\n\n## 二，Cesium能做什么？\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1721024608041-abcdcded-9494-435a-898a-bbdf8b268dc3.png)\n\nCesium的知识体系，跨GIS、Web前端和图形学。\n\nCesium用于地理数据可视化。支持海量数据的高效渲染，支持时间序列动态数据的三维可视化，具备太阳、大气、云雾等地理环境要素的动态模拟和地形等要素的加载绘制。包含丰富的可用工具。即Cesium基本控件所提供的工具，如地理编码器，图层选择器等。\n\nCesium在项目中的定位如下图：\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1721024726052-5b18cae5-d1f5-4c89-afa6-96dd6f16983d.png)\n\n主要的功能有：\n\n1.  使用3d tiles格式流式加载各种不同的3d数据，包含倾斜摄影模型、三维建筑物、CAD和BIM的外部和内部，点云数据。并支持样式配置和用户交互操作。\n2.  全球高精度地形数据可视化，支持地形夸张效果、以及可编程实现的等高线和坡度分析效果。\n3.  支持多种资源的图像图层，包括WMS，TMS，WMTS以及时序图像。图像支持透明度叠加、亮度、对比度、GAMMA、色调、饱和度都可以动态调整。支持图像的卷帘对比。\n4.  支持标准的矢量格式KML、GeoJSON、TopoJSON、以及矢量的贴地效果。\n5.  三维模型支持gltf2.0标准的PRB材质、动画、蒙皮和变形效果。贴地以及高亮效果。\n6.  使用CZML支持动态时序数据的展示。\n7.  支持各种几何体：点、线、面、标注、公告牌、立方体、球体、椭圆体、圆柱体、走廊、管径、墙体。\n8.  可视化效果包括：基于太阳位置的阴影、自身阴影、柔和阴影。\n9.  支持大气、雾、太阳、阳光、月亮、星星、水面。\n10.  粒子特效：烟、火、火花。\n11.  地形、模型、3d tiles模型的面裁剪。\n12.  对象点选和地形点选。\n13.  支持鼠标和触摸操作的缩放、渲染、惯性平移、飞行、任意视角、地形碰撞检测。\n14.  支持3d地球、2d地图、2.5d哥伦布模式。3d视图可以使用透视和正视两种投影方式。支持点、标注、公告牌的聚集效果。\n\n## 三，Cesium 的依赖性\n\n①基于HTML5标准，无插件，跨平台  \n②无法独立运行，依赖于浏览器  \n③浏览器基于HTTP协议，Cesium正确运行必须有HTTP Server  \n④HTTP Server的实现不限于开发语言和服务器（可不学nodejs）\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1721025007022-cde626e2-9a53-40e1-8b8b-3cd1d2974447.png)\n\n四，Cesium 学习参考\n\nCesium做为三维[GIS开发](https://so.csdn.net/so/search?q=GIS%E5%BC%80%E5%8F%91&spm=1001.2101.3001.7020)最火爆的前端框架，在三维数据管理、三维地形分析、动态场景可视化等方面广泛应用。\n\nCesium学习可用参考的文档有：  \n1.官网API文档：[官网](https://www.cesium.com/learn/)  \n2.官网沙盒例子：[官网](https://sandcastle.cesium.com/)  \n3.Cesiumlab  \n4.Cesium中文网\n\n## 四、Cesium 本地运行\n\n### (一) 下载官网文件\n\n打开官网地址，在Platform菜单下找到Downloads，打开下载页面。\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1731642633596-af34b576-33d0-4fe3-a5c1-568e9793f3c7.png)\n\n可以看到最新的版本是1.123，下载cesium包\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1731646550767-9ea4a706-3e82-4cab-916b-017ccb3bde8e.png)\n\n### (二) 安装依赖、运行\n\n下载解压后得到这个文件，\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1731650938723-eaee06f1-6afb-4f7b-8a10-d42eff3c5e3f.png)\n\n然后用编辑器打开，安装依赖\n\n```javascript\nnpm install\n```\n\n启动项目\n\n```javascript\nyarn run start\n```\n\n成功后结果如下，打开地址\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1731651172763-baceee90-046d-4bf3-994a-7251f8bdee6a.png)\n\n### (三) 功能界面\n\n界面如下：\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1731651326147-158350a1-d036-4cfd-94ef-670670847984.png)\n\n需要重点注意的有两个，分别是**Documentation**(API文档)和\\*\\*Sandcastle \\*\\*(沙盒)。\n\n可以在开发的过程中查看开发文档，帮助我们更好的了解API，查询各接口用途、使用方式、参数情况等等\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1731651462353-02b27488-3bbb-4201-aa42-5b7a5506c21a.png)\n\n另外一个是Sandcastle,Cesium为我们提供了一个沙盒测试环境，通过Sandcastle文件可以查看所有的示例程序代码，也可以在这里编写测试代码。\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1731651788822-850e01d1-5ebf-42e1-bb1b-34f9439bbe24.png)\n\n### (四) 文档结构\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1731652593502-0236cbb1-0725-4133-9950-be6cd81604e4.png)', '<p>官网：<a href=\"https://cesium.com/\" target=\"\">Cesium: The Platform for 3D Geospatial</a></p><p>中文API文档：<a href=\"http://cesium.xin/cesium/cn/Documentation1.62/index.html\" target=\"\">Cesium中文api文档 | Index - Cesium Documentation</a></p><h2>一，Cesium 简介</h2><p><strong>Cesium</strong>是AGI公司计算机图形开发小组与2011年研发的三维地球和地图可视化开源JavaScript库，Cesium一词来源于化学元素铯，铯是制造原子钟的关键元素，研发小组通过命名强调Cesium产品精益求精，专注时间数据可视化。</p><p>Cesium为三维GIS提供了一个高效的数据可视化平台。即：</p><ol><li>Cesium是一个跨平台、跨浏览器的<strong>展示三维地球和地图的JavaScript库</strong></li><li>Cesium使用WebGL来进行硬件加速图形，使用时不需要任何插件支持。</li><li>Cesium是基于Apache2.0许可的开源程序，可以免费用于商业和非商业用途。</li></ol><h2>二，Cesium能做什么？</h2><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1721024608041-abcdcded-9494-435a-898a-bbdf8b268dc3.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p>Cesium的知识体系，跨GIS、Web前端和图形学。</p><p>Cesium用于地理数据可视化。支持海量数据的高效渲染，支持时间序列动态数据的三维可视化，具备太阳、大气、云雾等地理环境要素的动态模拟和地形等要素的加载绘制。包含丰富的可用工具。即Cesium基本控件所提供的工具，如地理编码器，图层选择器等。</p><p>Cesium在项目中的定位如下图：</p><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1721024726052-5b18cae5-d1f5-4c89-afa6-96dd6f16983d.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p>主要的功能有：</p><ol><li>使用3d tiles格式流式加载各种不同的3d数据，包含倾斜摄影模型、三维建筑物、CAD和BIM的外部和内部，点云数据。并支持样式配置和用户交互操作。</li><li>全球高精度地形数据可视化，支持地形夸张效果、以及可编程实现的等高线和坡度分析效果。</li><li>支持多种资源的图像图层，包括WMS，TMS，WMTS以及时序图像。图像支持透明度叠加、亮度、对比度、GAMMA、色调、饱和度都可以动态调整。支持图像的卷帘对比。</li><li>支持标准的矢量格式KML、GeoJSON、TopoJSON、以及矢量的贴地效果。</li><li>三维模型支持gltf2.0标准的PRB材质、动画、蒙皮和变形效果。贴地以及高亮效果。</li><li>使用CZML支持动态时序数据的展示。</li><li>支持各种几何体：点、线、面、标注、公告牌、立方体、球体、椭圆体、圆柱体、走廊、管径、墙体。</li><li>可视化效果包括：基于太阳位置的阴影、自身阴影、柔和阴影。</li><li>支持大气、雾、太阳、阳光、月亮、星星、水面。</li><li>粒子特效：烟、火、火花。</li><li>地形、模型、3d tiles模型的面裁剪。</li><li>对象点选和地形点选。</li><li>支持鼠标和触摸操作的缩放、渲染、惯性平移、飞行、任意视角、地形碰撞检测。</li><li>支持3d地球、2d地图、2.5d哥伦布模式。3d视图可以使用透视和正视两种投影方式。支持点、标注、公告牌的聚集效果。</li></ol><h2>三，Cesium 的依赖性</h2><p><span style=\"color: rgb(77, 77, 77);\">①基于HTML5标准，无插件，跨平台</span><br><span style=\"color: rgb(77, 77, 77);\">②无法独立运行，依赖于浏览器</span><br><span style=\"color: rgb(77, 77, 77);\">③浏览器基于HTTP协议，Cesium正确运行必须有HTTP Server</span><br><span style=\"color: rgb(77, 77, 77);\">④HTTP Server的实现不限于开发语言和服务器（可不学nodejs）</span></p><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1721025007022-cde626e2-9a53-40e1-8b8b-3cd1d2974447.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p>四，Cesium 学习参考</p><p><span style=\"color: rgb(77, 77, 77);\">Cesium做为三维</span><a href=\"https://so.csdn.net/so/search?q=GIS%E5%BC%80%E5%8F%91&spm=1001.2101.3001.7020\" target=\"\">GIS开发</a><span style=\"color: rgb(77, 77, 77);\">最火爆的前端框架，在三维数据管理、三维地形分析、动态场景可视化等方面广泛应用。</span></p><p><span style=\"color: rgb(77, 77, 77);\">Cesium学习可用参考的文档有：<br> 1.官网API文档：</span><a href=\"https://www.cesium.com/learn/\" target=\"\">官网</a><span style=\"color: rgb(77, 77, 77);\"><br> 2.官网沙盒例子：</span><a href=\"https://sandcastle.cesium.com/\" target=\"\">官网</a><span style=\"color: rgb(77, 77, 77);\"><br> 3.Cesiumlab<br> 4.Cesium中文网</span></p><h2><span style=\"color: rgb(77, 77, 77);\">四、Cesium 本地运行</span></h2><h3>(一) 下载官网文件</h3><p><span style=\"color: rgb(51, 51, 51);\">打开官网地址，在Platform菜单下找到Downloads，打开下载页面。</span></p><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1731642633596-af34b576-33d0-4fe3-a5c1-568e9793f3c7.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p>可以看到最新的版本是1.123，下载cesium包</p><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1731646550767-9ea4a706-3e82-4cab-916b-017ccb3bde8e.png\" alt=\"\" data-href=\"\" style=\"\"/></p><h3>(二) 安装依赖、运行</h3><p>下载解压后得到这个文件，</p><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1731650938723-eaee06f1-6afb-4f7b-8a10-d42eff3c5e3f.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p>然后用编辑器打开，安装依赖</p><pre><code class=\"language-javascript\">npm install\n</code></pre><p>启动项目</p><pre><code class=\"language-javascript\">yarn run start\n</code></pre><p>成功后结果如下，打开地址</p><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1731651172763-baceee90-046d-4bf3-994a-7251f8bdee6a.png\" alt=\"\" data-href=\"\" style=\"\"/></p><h3>(三) 功能界面</h3><p>界面如下：</p><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1731651326147-158350a1-d036-4cfd-94ef-670670847984.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p>需要重点注意的有两个，分别是<strong>Documentation</strong>(API文档)和**Sandcastle **(沙盒)。</p><p><span style=\"color: rgb(51, 51, 51);\">可以在开发的过程中查看开发文档，帮助我们更好的了解API，查询各接口用途、使用方式、参数情况等等</span></p><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1731651462353-02b27488-3bbb-4201-aa42-5b7a5506c21a.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p>另外一个是Sandcastle,Cesium为我们提供了一个沙盒测试环境，通过Sandcastle文件可以查看所有的示例程序代码，也可以在这里编写测试代码。</p><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1731651788822-850e01d1-5ebf-42e1-bb1b-34f9439bbe24.png\" alt=\"\" data-href=\"\" style=\"\"/></p><h3>(四) 文档结构</h3><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1731652593502-0236cbb1-0725-4133-9950-be6cd81604e4.png\" alt=\"\" data-href=\"\" style=\"\"/></p>', 'gis', 'GIS', 'success', '📝', 'linear-gradient(135deg, #ffecd2 0%, #fcb69f 100%)', 1, 0, 0, 0, 0, '2026-07-01 21:22:04', '2026-07-01 21:22:04');
INSERT INTO sea_pack.`blog_article` VALUES (4, 'Express 基础', '', '# 一，Express 简介\n\n## (一) 什么是Express\n\nExpress 的中文官网：[https://www.expressjs.com.cn/](https://www.expressjs.com.cn/)\n\n  \n\n官方给出的概念：Express 是基于 Node.js 平台，快速、开放、极简的 Web 开发框架。\n\n  \n\n通俗的理解：Express 的作用和 Node.js 内置的 http 模块类似，是专门用来创建 Web 服务器的。\n\n  \n\n**Express 的本质**：就是一个 npm 上的第三方包，提供了快速创建 Web 服务器的便捷方法。\n\n  \n\n## (二) 进一步理解 Express\n\n思考：不使用 Express 能否创建 Web 服务器？\n\n答案：能，使用 Node.js 提供的原生 http 模块即可。\n\n  \n\n思考：既生瑜何生亮（有了 http 内置模块，为什么还有用 Express）？\n\n答案：http 内置模块用起来很复杂，开发效率低；Express 是基于内置的 http 模块进一步封装出来的，能够极大的提高开发效率。\n\n  \n\n思考：http 内置模块与 Express 是什么关系？\n\n答案：类似于浏览器中 Web API 和 jQuery 的关系。后者是基于前者进一步封装出来的。\n\n  \n\n## (三) Express 能做什么\n\n对于前端程序员来说，最常见的两种服务器，分别是：\n\n1.  Web 网站服务器：专门对外提供 Web 网页资源的服务器。\n2.  API 接口服务器：专门对外提供 API 接口的服务器。\n\n使用 Express，我们可以方便、快速的创建 Web 网站的服务器或 API 接口的服务器。\n\n  \n\n# 二，Express 的基本使用\n\n## (一) 安装\n\n```json\nnpm install express\n```\n\n## (二) 创建基本的Web服务器\n\n```javascript\n// 1.引入 express\nconst express = require(\"express\");\n\n// 2.创建 web 服务器\nconst app = express();\n\n// 3.调用 app.listen(端口号，启动成功后的回调)，启动服务器\napp.listen(8099,()=>{\n  console.log(\"express server running at http://127.0.0.1:8099\")\n})\n\n```\n\n## (三)监听 Get 请求\n\n通过 app.get() 方法，可以监听客户端的 GET 请求，具体的语法格式如下：\n\n```javascript\n//参数1：客户端请求的URL地址\n//参数2：请求对应的处理函数\n//  req:请求对象(包含了与请求相关的属性和方法)\n//  req:响应对象(包含了与响应相关的属性和方法)\napp.get(\"请求URL\",function(req,res){/*处理函数*/})\n```\n\n## (四) 监听post 请求\n\n通过 app.post() 方法，可以监听客户端的 POST 请求，具体的语法格式如下：\n\n```javascript\n//参数1：客户端请求的URL地址\n//参数2：请求对应的处理函数\n//  req:请求对象(包含了与请求相关的属性和方法)\n//  req:响应对象(包含了与响应相关的属性和方法)\napp.post(\"请求URL\",function(req,res){/*处理函数*/})\n```\n\n## (五) 把内容响应给客户端\n\n通过 res.send() 方法，可以把处理好的内容，发送给客户端：\n\n```javascript\n// 1.引入 express\nconst express = require(\"express\");\n\n// 2.创建 web 服务器\nconst app = express();\n\n//参数1：客户端请求的URL地址\n//参数2：请求对应的处理函数\n//  req:请求对象(包含了与请求相关的属性和方法)\n//  req:响应对象(包含了与响应相关的属性和方法)\napp.get(\"/user\",(req,res)=>{\n  res.send({name:\"zs\",age:18})\n});\n\napp.post(\"/update/user\",(req,res)=>{\n  res.send({code:200,data:true,message:\"\"})\n})\n\n// 3.调用 app.listen(端口号，启动成功后的回调)，启动服务器\napp.listen(8099,()=>{\n  console.log(\"express server running at http://127.0.0.1:8099\")\n})\n\n```\n\n启动服务\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1718853991339-23b9e911-ab77-4cba-90f8-193c098796bc.png)\n\n调用接口\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1718854025734-9dfa6d73-f00b-4c8d-9872-7232ba6f1c42.png)\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1718854043381-3286ad1d-8e1f-4868-8377-1ef618cb9430.png)\n\n## (六) 获取URL 中参数\n\n### 查询参数\n\n通过 req.query 对象，可以访问到客户端通过查询字符串的形式，发送到服务器的参数。\n\n  \n\n需要注意的是：\n\n*   req.query 默认是一个空对象\n*   客户端使用?name=张三&age=25 这种查询字符串的形式，发送到服务器的参数，可以通过req.query访问到\n\n```javascript\napp.get(\"/user\",(req,res)=>{\n  res.send(req.query)\n});\n```\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1718854325328-d603deda-77ef-49c4-8c17-1ec40d062bfe.png)\n\n### 动态参数\n\n通过 req.params 对象，可以访问到 URL 中，通过 **:** 匹配到的动态参数。\n\n```javascript\napp.get(\"/user/:id\",(req,res)=>{\n  console.log(req.params)\n  res.send(req.params)\n});\n```\n\n![](https://cdn.nlark.com/yuque/0/2024/png/35619076/1718854985138-abc0b302-09cb-4f5c-9b50-54986deabc4b.png)\n\n# 三，托管静态资源\n\n## (一) express.static()\n\nexpress 提供了一个非常好用的函数，叫做 express.static()，通过它，我们可以非常方便地创建一个静态资源服务器，\n\n例如，通过如下代码就可以将 public 目录下的图片、CSS 文件、JavaScript 文件对外开放访问了：\n\n```javascript\napp.use(express.static(\"public\"))\n```\n\n现在，你就可以访问 public 目录中的所有文件了：\n\n*   http://localhost:3000/images/bg.jpg\n*   http://localhost:3000/css/style.css\n*   http://localhost:3000/js/login.js\n\n**注意：**Express 在指定的静态目录中查找文件，并对外提供资源的访问路径。 因此，存放静态文件的目录名不会出现在 URL 中。\n\n  \n\n## (二) 托管多个静态资源目录\n\n如果要托管多个静态资源目录，请多次调用 express.static() 函数：\n\n```javascript\napp.use(express.static(\"public\"))\napp.use(express.static(\"file\"))\n```\n\n访问静态资源文件时，express.static() 函数会根据**目录的添加顺序查找所需的文件**。\n\n注意：如果按此种方式，如 public 和 file 目录下都有 index.html，则访问静态资源文件index.html 时永远是查找public 目录下的 index.html 文件。\n\n## (三) 挂载路径前缀\n\n如果希望在托管的静态资源访问路径之前，挂载路径前缀，则可以使用如下的方式：\n\n```javascript\napp.use(\'/public\',express.static(\"public\"))\n```\n\n现在，你就可以通过带有 /public 前缀地址来访问 public 目录中的文件了：\n\n*   http://localhost:3000/public/images/kitten.jpg\n*   http://localhost:3000/public/css/style.css\n*   http://localhost:3000/public/js/app.js', '<h1>一，Express 简介</h1><h2>(一) 什么是Express</h2><p><span style=\"color: rgb(0, 0, 0);\">Express 的中文官网：</span><a href=\"https://www.expressjs.com.cn/\" target=\"\">https://www.expressjs.com.cn/</a></p><p><br></p><p><span style=\"color: rgb(0, 0, 0);\">官方给出的概念：Express 是</span><span style=\"color: rgb(255, 0, 0);\">基于 Node.js 平台</span><span style=\"color: rgb(0, 0, 0);\">，</span><span style=\"color: rgb(4, 127, 253);\">快速、开放、极简</span><span style=\"color: rgb(0, 0, 0);\">的 </span><span style=\"color: rgb(255, 0, 0);\">Web 开发框架</span><span style=\"color: rgb(0, 0, 0);\">。 </span></p><p><br></p><p><span style=\"color: rgb(0, 0, 0);\">通俗的理解：Express 的作用和 Node.js 内置的 http 模块类似，</span><span style=\"color: rgb(255, 0, 0);\">是专门用来创建 Web 服务器的</span><span style=\"color: rgb(0, 0, 0);\">。 </span></p><p><br></p><p><strong>Express 的本质</strong><span style=\"color: rgb(0, 0, 0);\">：就是一个 npm 上的第三方包，提供了快速创建 Web 服务器的便捷方法。</span></p><p><br></p><h2><span style=\"color: rgb(0, 0, 0);\">(二) </span><span style=\"color: rgb(89, 89, 89);\">进一步理解 Express</span></h2><p><span style=\"color: rgb(255, 0, 0);\">思考：</span><span style=\"color: rgb(0, 0, 0);\">不使用 Express 能否创建 Web 服务器？ </span></p><p><span style=\"color: rgb(4, 127, 253);\">答案：</span><span style=\"color: rgb(0, 0, 0);\">能，使用 Node.js 提供的原生 http 模块即可。 </span></p><p><br></p><p><span style=\"color: rgb(255, 0, 0);\">思考：</span><span style=\"color: rgb(0, 0, 0);\">既生瑜何生亮（有了 http 内置模块，为什么还有用 Express）？ </span></p><p><span style=\"color: rgb(4, 127, 253);\">答案：</span><span style=\"color: rgb(0, 0, 0);\">http 内置模块用起来很复杂，开发效率低；Express 是基于内置的 http 模块进一步封装出来的，能够极大的提高开发效率。 </span></p><p><br></p><p><span style=\"color: rgb(255, 0, 0);\">思考：</span><span style=\"color: rgb(0, 0, 0);\">http 内置模块与 Express 是什么关系？ </span></p><p><span style=\"color: rgb(4, 127, 253);\">答案：</span><span style=\"color: rgb(0, 0, 0);\">类似于浏览器中 Web API 和 jQuery 的关系。后者是基于前者进一步封装出来的。</span></p><p><br></p><h2><span style=\"color: rgb(0, 0, 0);\">(三) Express 能做什么</span></h2><p><span style=\"color: rgb(0, 0, 0);\">对于前端程序员来说，最常见的</span><span style=\"color: rgb(4, 127, 253);\">两种</span><span style=\"color: rgb(0, 0, 0);\">服务器，分别是： </span></p><ol><li><span style=\"color: rgb(0, 0, 0);\"> </span><span style=\"color: rgb(255, 0, 0);\">Web 网站服务器</span><span style=\"color: rgb(0, 0, 0);\">：专门对外提供 Web 网页资源的服务器。 </span></li><li><span style=\"color: rgb(0, 0, 0);\"> </span><span style=\"color: rgb(255, 0, 0);\">API 接口服务器</span><span style=\"color: rgb(0, 0, 0);\">：专门对外提供 API 接口的服务器。 </span></li></ol><p><span style=\"color: rgb(0, 0, 0);\">使用 Express，我们可以方便、快速的创建 </span><span style=\"color: rgb(4, 127, 253);\">Web 网站</span><span style=\"color: rgb(0, 0, 0);\">的服务器或 </span><span style=\"color: rgb(4, 127, 253);\">API 接口</span><span style=\"color: rgb(0, 0, 0);\">的服务器。</span></p><p><br></p><h1><span style=\"color: rgb(0, 0, 0);\">二，Express 的基本使用</span></h1><h2>(一) 安装</h2><pre><code class=\"language-json\">npm install express\n</code></pre><h2>(二) 创建基本的Web服务器</h2><pre><code class=\"language-javascript\">// 1.引入 express\nconst express = require(\"express\");\n\n// 2.创建 web 服务器\nconst app = express();\n\n// 3.调用 app.listen(端口号，启动成功后的回调)，启动服务器\napp.listen(8099,()=&gt;{\n  console.log(\"express server running at http://127.0.0.1:8099\")\n})\n\n</code></pre><h2>(三)监听 Get 请求</h2><p><span style=\"color: rgb(0, 0, 0);\">通过 app.get() 方法，可以监听客户端的 GET 请求，具体的语法格式如下：</span></p><pre><code class=\"language-javascript\">//参数1：客户端请求的URL地址\n//参数2：请求对应的处理函数\n//  req:请求对象(包含了与请求相关的属性和方法)\n//  req:响应对象(包含了与响应相关的属性和方法)\napp.get(\"请求URL\",function(req,res){/*处理函数*/})\n</code></pre><h2>(四) 监听post 请求</h2><p><span style=\"color: rgb(0, 0, 0);\">通过 app.post() 方法，可以监听客户端的 POST 请求，具体的语法格式如下：</span></p><pre><code class=\"language-javascript\">//参数1：客户端请求的URL地址\n//参数2：请求对应的处理函数\n//  req:请求对象(包含了与请求相关的属性和方法)\n//  req:响应对象(包含了与响应相关的属性和方法)\napp.post(\"请求URL\",function(req,res){/*处理函数*/})\n</code></pre><h2>(五) 把内容响应给客户端</h2><p><span style=\"color: rgb(0, 0, 0);\">通过 </span><span style=\"color: rgb(255, 0, 0);\">res.send() </span><span style=\"color: rgb(0, 0, 0);\">方法，可以把处理好的内容，发送给客户端：</span></p><pre><code class=\"language-javascript\">// 1.引入 express\nconst express = require(\"express\");\n\n// 2.创建 web 服务器\nconst app = express();\n\n//参数1：客户端请求的URL地址\n//参数2：请求对应的处理函数\n//  req:请求对象(包含了与请求相关的属性和方法)\n//  req:响应对象(包含了与响应相关的属性和方法)\napp.get(\"/user\",(req,res)=&gt;{\n  res.send({name:\"zs\",age:18})\n});\n\napp.post(\"/update/user\",(req,res)=&gt;{\n  res.send({code:200,data:true,message:\"\"})\n})\n\n// 3.调用 app.listen(端口号，启动成功后的回调)，启动服务器\napp.listen(8099,()=&gt;{\n  console.log(\"express server running at http://127.0.0.1:8099\")\n})\n\n</code></pre><p>启动服务</p><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1718853991339-23b9e911-ab77-4cba-90f8-193c098796bc.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p>调用接口</p><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1718854025734-9dfa6d73-f00b-4c8d-9872-7232ba6f1c42.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1718854043381-3286ad1d-8e1f-4868-8377-1ef618cb9430.png\" alt=\"\" data-href=\"\" style=\"\"/></p><h2>(六) 获取URL 中参数</h2><h3>查询参数</h3><p><span style=\"color: rgb(0, 0, 0);\">通过 </span><span style=\"color: rgb(255, 0, 0);\">req.query </span><span style=\"color: rgb(0, 0, 0);\">对象，可以访问到客户端通过</span><span style=\"color: rgb(255, 0, 0);\">查询字符串</span><span style=\"color: rgb(0, 0, 0);\">的形式，发送到服务器的参数。</span></p><p><br></p><p><span style=\"color: rgb(0, 0, 0);\">需要注意的是：</span></p><ul><li>req.query 默认是一个空对象</li><li>客户端使用?name=张三&age=25 这种查询字符串的形式，发送到服务器的参数，可以通过req.query访问到</li></ul><pre><code class=\"language-javascript\">app.get(\"/user\",(req,res)=&gt;{\n  res.send(req.query)\n});\n</code></pre><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1718854325328-d603deda-77ef-49c4-8c17-1ec40d062bfe.png\" alt=\"\" data-href=\"\" style=\"\"/></p><h3>动态参数</h3><p><span style=\"color: rgb(0, 0, 0);\">通过 </span><span style=\"color: rgb(255, 0, 0);\">req.params </span><span style=\"color: rgb(0, 0, 0);\">对象，可以访问到 URL 中，通过 </span><strong>: </strong><span style=\"color: rgb(0, 0, 0);\">匹配到的</span><span style=\"color: rgb(255, 0, 0);\">动态参数</span><span style=\"color: rgb(0, 0, 0);\">。</span></p><pre><code class=\"language-javascript\">app.get(\"/user/:id\",(req,res)=&gt;{\n  console.log(req.params)\n  res.send(req.params)\n});\n</code></pre><p><img src=\"https://cdn.nlark.com/yuque/0/2024/png/35619076/1718854985138-abc0b302-09cb-4f5c-9b50-54986deabc4b.png\" alt=\"\" data-href=\"\" style=\"\"/></p><h1>三，托管静态资源</h1><h2>(一) <span style=\"color: rgb(89, 89, 89);\">express.static()</span></h2><p><span style=\"color: rgb(0, 0, 0);\">express 提供了一个非常好用的函数，叫做 </span><span style=\"color: rgb(255, 0, 0);\">express.static()</span><span style=\"color: rgb(0, 0, 0);\">，通过它，我们可以</span><span style=\"color: rgb(255, 0, 0);\">非常方便地创建</span><span style=\"color: rgb(0, 0, 0);\">一个</span><span style=\"color: rgb(255, 0, 0);\">静态资源服务器</span><span style=\"color: rgb(0, 0, 0);\">， </span></p><p><span style=\"color: rgb(0, 0, 0);\">例如，通过如下代码就可以将 public 目录下的图片、CSS 文件、JavaScript 文件对外开放访问了：</span></p><pre><code class=\"language-javascript\">app.use(express.static(\"public\"))\n</code></pre><p><span style=\"color: rgb(0, 0, 0);\">现在，你就可以访问 public 目录中的所有文件了： </span></p><ul><li><span style=\"color: rgb(0, 0, 0);\">http://localhost:3000</span><span style=\"color: rgb(4, 127, 253);\">/images/bg.jpg </span></li><li><span style=\"color: rgb(0, 0, 0);\">http://localhost:3000</span><span style=\"color: rgb(4, 127, 253);\">/css/style.css </span></li><li><span style=\"color: rgb(0, 0, 0);\">http://localhost:3000</span><span style=\"color: rgb(4, 127, 253);\">/js/login.js</span></li></ul><p><strong>注意：</strong><span style=\"color: rgb(0, 0, 0);\">Express 在</span><span style=\"color: rgb(255, 0, 0);\">指定的</span><span style=\"color: rgb(0, 0, 0);\">静态目录中查找文件，并对外提供资源的访问路径。 因此，</span><span style=\"color: rgb(255, 0, 0);\">存放静态文件的目录名不会出现在 URL 中</span><span style=\"color: rgb(0, 0, 0);\">。</span></p><p><br></p><h2><span style=\"color: rgb(0, 0, 0);\">(二) 托管多个静态资源目录</span></h2><p><span style=\"color: rgb(0, 0, 0);\">如果要托管多个静态资源目录，请多次调用 express.static() 函数：</span></p><pre><code class=\"language-javascript\">app.use(express.static(\"public\"))\napp.use(express.static(\"file\"))\n</code></pre><p><span style=\"color: rgb(0, 0, 0);\">访问静态资源文件时，express.static() 函数会根据</span><strong>目录的添加顺序查找所需的文件</strong><span style=\"color: rgb(0, 0, 0);\">。</span></p><p>注意：如果按此种方式，如 public 和 file 目录下都有 index.html，则访问静态资源文件index.html 时永远是查找public 目录下的 index.html 文件。</p><h2>(三) <span style=\"color: rgb(0, 0, 0);\">挂载路径前缀</span></h2><p><span style=\"color: rgb(0, 0, 0);\">如果希望在托管的</span><span style=\"color: rgb(255, 0, 0);\">静态资源访问路径</span><span style=\"color: rgb(0, 0, 0);\">之前，</span><span style=\"color: rgb(255, 0, 0);\">挂载路径前缀</span><span style=\"color: rgb(0, 0, 0);\">，则可以使用如下的方式：</span></p><pre><code class=\"language-javascript\">app.use(\'/public\',express.static(\"public\"))\n</code></pre><p><span style=\"color: rgb(0, 0, 0);\">现在，你就可以通过带有 </span><span style=\"color: rgb(4, 127, 253);\">/public </span><span style=\"color: rgb(0, 0, 0);\">前缀地址来访问 public 目录中的文件了： </span></p><ul><li><span style=\"color: rgb(0, 0, 0);\">http://localhost:3000</span><span style=\"color: rgb(4, 127, 253);\">/public</span><span style=\"color: rgb(0, 0, 0);\">/images/kitten.jpg </span></li><li><span style=\"color: rgb(0, 0, 0);\">http://localhost:3000</span><span style=\"color: rgb(4, 127, 253);\">/public</span><span style=\"color: rgb(0, 0, 0);\">/css/style.css </span></li><li><span style=\"color: rgb(0, 0, 0);\">http://localhost:3000</span><span style=\"color: rgb(4, 127, 253);\">/public</span><span style=\"color: rgb(0, 0, 0);\">/js/app.js</span></li></ul>', 'other', '其他', 'danger', '📝', 'linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%)', 1, 0, 0, 0, 0, '2026-07-01 21:25:02', '2026-07-01 21:25:02');
INSERT INTO sea_pack.`blog_article` VALUES (5, 'v-model指令的实现', '', '## 前言\n\n在之前，我们手写了vue数据是如何响应的代码，在这个基础上，再来探究下其双向绑定的v-model是如何实现的。\n\n## 创建Vue类实现数据初始化操作\n\nVue类中主要实现的功能如下：\n\n1.  将Vue接收到的对象数据复制一份存储到Vue类的实例 \\*\\*$options \\*\\*身上\n2.  将Vue接收的对象数据存储到Vue类实例的 \\*\\*\\_data \\*\\*上\n3.  调用 \\*\\*observe \\*\\*方法，将 **\\_data** 数据变成响应式的\n4.  将 \\_data 上的数据循环遍历一份放到 Vue 实例上\n5.  初始化watch，将设置的watch监控项数据放到 \\*\\*Watcher \\*\\*里面进行监控\n\n```javascript\nimport {observe} from \"../vue2ResponsivePrinciple/observe\";\nimport Watcher from \"../vue2ResponsivePrinciple/Watcher\";\nimport Compile from \"./Compile\";\nexport default class Vue{\n    constructor(options){\n        //把参数options对象存为$options;\n        this.$options = options || {};\n        //存储数据\n        this._data = options.data || undefined;\n        //将数据变成响应式的\n        observe(this._data);\n        // 默认数据变成响应式的,将_data上的数据复制一份到this上。\n        this._initData()\n        //调用默认的Watcher\n        this._initWatch()\n        //进行模板编译\n        new Compile(options.el,this);\n    }\n    _initData(){\n        let self = this;\n        Object.keys(this._data).forEach(key=>{\n            Object.defineProperty(self,key,{\n                get:()=>{\n                    return self._data[key];\n                },\n                set:(newValue)=>{\n                    self._data[key] = newValue;\n                }\n            })\n        })\n    }\n\n    _initWatch(){\n        let self = this;\n        //获取参数里面的watch项\n        let watch = this.$options.watch || {};\n        //设置watch项里面的监听\n        Object.keys(watch).forEach(key=>{\n            new Watcher(self,key,watch[key]);\n        })\n    }\n}\n```\n\n## 创建编译类Compile\n\n#### Compile类中实现的功能如下\n\n1.  使用 \\*\\*fragment \\*\\*节点替代虚拟节点，将获取到的dom树节点放到fragment节点上。\n2.  编译dom树，循环遍历节点，根据节点类型不同执行不同的操作。这里主要用到了元素节点和文本节点。\n3.  上树，将操作好的 fragment 节点放到 el 上。\n\n```javascript\nimport Watcher from \"../vue2ResponsivePrinciple/Watcher\";\nexport default class Compile{\n    constructor(el,vue) {\n        //vue实例\n        this.$vue = vue;\n        //挂载点\n        this.$el = document.querySelector(el);\n        if(this.$el){\n            // 调用函数，让节点变为fragment，类似于mustache中的tokens。实际上用的是AST，这里就是轻量级的，fragment\n            let $fragment = this.node2Fragment(this.$el);\n            //编译\n            this.compile($fragment);\n            //替换好的内容要上树\n            this.$el.appendChild($fragment);\n        }\n    }\n\n    node2Fragment(el){\n        /**\n         * 创造一个DocumentFragment类型节点，可以把它当作虚拟节点,消耗小\n         * 主要作用：充当其他要被添加到文档的节点的仓库，也就是充当初始父节点\n         * 其parentNode值为空\n         * @type {DocumentFragment}\n         */\n        let fragment = document.createDocumentFragment();\n        let child;\n        //获取文档节点中的第一个节点，并将其赋值给child\n        while(child = el.firstChild){\n            fragment.appendChild(child);\n        }\n        return fragment;\n    }\n\n    //编译\n    compile(el){\n        ...\n    }\n}\n\n```\n\n#### 对于文本节点的操作\n\n1.  获取文本节点上的文本，匹配其是否存在 双大括号( {{}} )语法，\n2.  通过 **getVueVal** 方法读取双大括号里面的值，\n3.  将双大括号的值作为监控项通过 \\*\\*Watcher \\*\\*监控(收集依赖)\n4.  当监控项值发生变化时(触发依赖)，通过**回调函数**将新值赋值到文本节点上\n\n到这里就实现了data中的数据值发生变化时同步更新界面上引用的数据\n\n```javascript\nimport Watcher from \"../vue2ResponsivePrinciple/Watcher\";\nexport default class Compile{\n    constructor(el,vue) {\n        ...\n    }\n\n    node2Fragment(el){\n        ...\n    }\n\n    //编译\n    compile(el){\n        let childNodes = el.childNodes;\n        let self = this;\n        //捕获{{}}文本数据\n        let reg = /\\{\\{(.*)\\}\\}/;\n        childNodes.forEach(node=>{\n            //获取节点的文本\n            let text = node.textContent;\n            //nodeType值为1，代表元素节点\n            if(node.nodeType == 1){\n                self.compileElement(node);\n            }else if(node.nodeType == 3 && reg.test(text)){\n                //nodeType值为3，代表文本节点\n                let name = text.match(reg)[1];\n                self.compileText(node,name);\n            }\n        })\n    }\n\n    compileElement(node){\n        ...\n    }\n\n    compileText(node,name){\n        //之前已经把data里面的数据循环遍历放到vue上了，所以可以传入vue\n        node.textContent = this.getVueVal(this.$vue,name);\n        //设置监控响应\n        new Watcher(this.$vue,name,(newValue)=>{\n            node.textContent = newValue;\n        })\n    }\n\n    //获取使用的值a.b.n\n    getVueVal(vue,exp){\n        let val = vue;\n        exp = exp.split(\".\");\n        exp.forEach(key=>{\n            val = val[key];\n        })\n        return val;\n    }\n}\n```\n\n#### 对于元素节点的操作\n\n1.  获取元素节点的属性，如class、id、style、type等等，也包含自定义的属性v-model、v-if等等。\n2.  循环遍历节点上的属性，找出是否含有v-model属性。\n3.  获取到v-model属性上的值。如下，v-model的值就为a.b.n\n\n```html\n<input type=\"text\" v-model=\"a.b.n\"/>\n```\n\n1.  使用 Watcher 对 a.b.n  进行监控，在回调函数中将新值赋值给元素节点的值。到这里就实现了Vue数据到界面视图的同步，即Vue中的数据进行变动时会将新值更新到界面上。\n2.  使用 getVueVal 获取a.b.n 对应的值，将值赋值给元素节点的值，实现绑定值的初始化\n3.  给元素节点设置addEventListener监听事件，触发事件时通过setVueVal方法将获取的新值赋值给监控项a.b.n对应的值。到这就实现了界面视图到Vue数据的同步，即界面的数据变动时，将变动值更新到Vue数据上。\n\n完整代码：\n\n```javascript\nimport Watcher from \"../vue2ResponsivePrinciple/Watcher\";\nexport default class Compile{\n    constructor(el,vue) {\n        //vue实例\n        this.$vue = vue;\n        //挂载点\n        this.$el = document.querySelector(el);\n        if(this.$el){\n            // 调用函数，让节点变为fragment，类似于mustache中的tokens。实际上用的是AST，这里就是轻量级的，fragment\n            let $fragment = this.node2Fragment(this.$el);\n            //编译\n            this.compile($fragment);\n            //替换好的内容要上树\n            this.$el.appendChild($fragment);\n        }\n    }\n\n    node2Fragment(el){\n        /**\n         * 创造一个DocumentFragment类型节点，可以把它当作虚拟节点,消耗小\n         * 主要作用：充当其他要被添加到文档的节点的仓库，也就是充当初始父节点\n         * 其parentNode值为空\n         * @type {DocumentFragment}\n         */\n        let fragment = document.createDocumentFragment();\n        let child;\n        //获取文档节点中的第一个节点，并将其赋值给child\n        while(child = el.firstChild){\n            fragment.appendChild(child);\n        }\n        return fragment;\n    }\n\n    //编译\n    compile(el){\n        let childNodes = el.childNodes;\n        let self = this;\n\n        //捕获{{}}文本数据\n        let reg = /\\{\\{(.*)\\}\\}/;\n\n        childNodes.forEach(node=>{\n            //获取节点的文本\n            let text = node.textContent;\n            //nodeType值为1，代表元素节点\n            if(node.nodeType == 1){\n                self.compileElement(node);\n            }else if(node.nodeType == 3 && reg.test(text)){\n                //nodeType值为3，代表文本节点\n                let name = text.match(reg)[1];\n                self.compileText(node,name);\n            }\n        })\n    }\n\n    compileElement(node){\n        //获取元素节点的属性，比如class,id等等。\n        let nodeAttrs = node.attributes;\n        //获取的nodeAttrs是一个类数组对象,将其转化为数组对象\n        let nodeAttrsArray = [...nodeAttrs];\n        let self = this;\n        nodeAttrsArray.forEach(attr=>{\n            //在这里分析指令\n            let attrName = attr.name;\n            let value = attr.value;\n            //指令都是v-开头的，取字符串2位后字符\n            let dir = attrName.substring(2);\n            //判断是否为指令\n            if(attrName.indexOf(\'v-\') == 0){\n                //双向绑定\n                if(dir == \'model\'){\n                    // console.log(\'捕捉到v-model指令\',node);\n                    //将实际值放入v-model绑定的值\n                    //此时vue中的数据改变会影响界面的数据，数据从vue流向界面。\n                    new Watcher(self.$vue,value,value=>{\n                        node.value = value;\n                    });\n                    //读取绑定的值\n                    let v = self.getVueVal(self.$vue,value);\n                    node.value = v;\n\n                    //添加界面数据变动影响vue里面的数据，通过给元素添加监听事件实现。\n                    node.addEventListener(\'input\',e=>{\n                        let newVal = e.target.value;\n                        self.setVueVal(self.$vue,value,newVal);\n                        v = newVal;\n                    })\n                }\n            }\n        })\n    }\n\n    compileText(node,name){\n        //之前已经把data里面的数据循环遍历放到vue上了，所以可以传入vue\n        node.textContent = this.getVueVal(this.$vue,name);\n        //设置监控响应\n        new Watcher(this.$vue,name,(newValue)=>{\n            node.textContent = newValue;\n        })\n    }\n\n    //获取使用的值a.b.n\n    getVueVal(vue,exp){\n        let val = vue;\n        exp = exp.split(\".\");\n        exp.forEach(key=>{\n            val = val[key];\n        })\n        return val;\n    }\n\n    //修改值\n    setVueVal(vue,exp,value){\n        let val = vue;\n        exp = exp.split(\".\");\n        exp.forEach((key,i)=>{\n            //获取最底层的值修改\n            if(i< exp.length - 1){\n                val = val[key]\n            }else{\n                val[key] = value;\n            }\n        })\n    }\n}\n\n```\n\n## index.js中引入测试\n\n通过webpack打包后的js文件中的方法和变量都会变成局部的，外部无法直接访问，因此可以将其添加到window上，方便外部访问。\n\n```javascript\nimport Vue from \'./Vue\'\nwindow.Vue = Vue;\n```\n\n## index.html主页测试\n\n这个index.html是初始模板，通过webpack打包后会使打包后的bundle.js文件自动的插入html模板文件中。\n\n使用setTimeout是在JS文件加载解析后在进行实例化Vue，防止其为空。\n\n```html\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Title</title>\n</head>\n<body>\n    <div id=\"app\">\n        {{a.b.n}}\n        <h2 id=\"h2\" >--------------------------------------</h2>\n        <input type=\"text\" v-model=\"a.b.n\"/>\n    </div>\n</body>\n<script>\n    let vm = null;\n    setTimeout(()=>{\n        vm = new Vue({\n            el:\"#app\",\n            data:{\n                a:{\n                    b:{\n                        n:10\n                    }\n                },\n                b:false,\n                c:55\n            },\n            watch:{\n                b:function(newValue,oldValue){\n                    console.log(newValue,oldValue)\n                }\n            }\n        });\n    },500);\n    console.log(vm);\n</script>\n</html>\n```\n\n## 测试结果\n\n![](https://cdn.nlark.com/yuque/0/2023/png/35619076/1687748884245-95f95611-26e9-4050-a0dc-58f0996a3b7d.png)\n\n最终实现了输入框和文本框同步，一个更改另一个数据也会同步更改。\n\n## 小结\n\nv-model如何实现数据双向绑定？\n\n1.  先通过observe实现对Vue数据的监听。\n2.  通过Watcher监控v-model绑定项，并在其回调函数里面将新值更新到界面。实现了从Vue中的数据到界面的流动。\n3.  通过给监控的元素节点添加addEventListener事件来监听元素的改变，并在其回调函数里将界面最新值更新到Vue数据中。从而实现了数据从界面流向Vue数据。', '<h2>前言</h2><p>在之前，我们手写了vue数据是如何响应的代码，在这个基础上，再来探究下其双向绑定的v-model是如何实现的。</p><h2>创建Vue类实现数据初始化操作</h2><p>Vue类中主要实现的功能如下：</p><ol><li>将Vue接收到的对象数据复制一份存储到Vue类的实例 **<span style=\"color: rgb(223, 42, 63);\">$options </span>**身上</li><li>将Vue接收的对象数据存储到Vue类实例的 **<span style=\"color: rgb(223, 42, 63);\">_data </span>**上</li><li>调用 **observe **方法，将 <strong>_data</strong> 数据变成响应式的</li><li>将 _data 上的数据循环遍历一份放到 Vue 实例上</li><li>初始化watch，将设置的watch监控项数据放到 **<span style=\"color: rgb(223, 42, 63);\">Watcher </span>**里面进行监控</li></ol><pre><code class=\"language-javascript\">import {observe} from \"../vue2ResponsivePrinciple/observe\";\nimport Watcher from \"../vue2ResponsivePrinciple/Watcher\";\nimport Compile from \"./Compile\";\nexport default class Vue{\n    constructor(options){\n        //把参数options对象存为$options;\n        this.$options = options || {};\n        //存储数据\n        this._data = options.data || undefined;\n        //将数据变成响应式的\n        observe(this._data);\n        // 默认数据变成响应式的,将_data上的数据复制一份到this上。\n        this._initData()\n        //调用默认的Watcher\n        this._initWatch()\n        //进行模板编译\n        new Compile(options.el,this);\n    }\n    _initData(){\n        let self = this;\n        Object.keys(this._data).forEach(key=&gt;{\n            Object.defineProperty(self,key,{\n                get:()=&gt;{\n                    return self._data[key];\n                },\n                set:(newValue)=&gt;{\n                    self._data[key] = newValue;\n                }\n            })\n        })\n    }\n\n    _initWatch(){\n        let self = this;\n        //获取参数里面的watch项\n        let watch = this.$options.watch || {};\n        //设置watch项里面的监听\n        Object.keys(watch).forEach(key=&gt;{\n            new Watcher(self,key,watch[key]);\n        })\n    }\n}\n</code></pre><h2>创建编译类Compile</h2><h4>Compile类中实现的功能如下</h4><ol><li>使用 **fragment **节点替代虚拟节点，将获取到的dom树节点放到fragment节点上。</li><li>编译dom树，循环遍历节点，根据节点类型不同执行不同的操作。这里主要用到了元素节点和文本节点。</li><li>上树，将操作好的 fragment 节点放到 el 上。</li></ol><pre><code class=\"language-javascript\">import Watcher from \"../vue2ResponsivePrinciple/Watcher\";\nexport default class Compile{\n    constructor(el,vue) {\n        //vue实例\n        this.$vue = vue;\n        //挂载点\n        this.$el = document.querySelector(el);\n        if(this.$el){\n            // 调用函数，让节点变为fragment，类似于mustache中的tokens。实际上用的是AST，这里就是轻量级的，fragment\n            let $fragment = this.node2Fragment(this.$el);\n            //编译\n            this.compile($fragment);\n            //替换好的内容要上树\n            this.$el.appendChild($fragment);\n        }\n    }\n\n    node2Fragment(el){\n        /**\n         * 创造一个DocumentFragment类型节点，可以把它当作虚拟节点,消耗小\n         * 主要作用：充当其他要被添加到文档的节点的仓库，也就是充当初始父节点\n         * 其parentNode值为空\n         * @type {DocumentFragment}\n         */\n        let fragment = document.createDocumentFragment();\n        let child;\n        //获取文档节点中的第一个节点，并将其赋值给child\n        while(child = el.firstChild){\n            fragment.appendChild(child);\n        }\n        return fragment;\n    }\n\n    //编译\n    compile(el){\n        ...\n    }\n}\n\n</code></pre><h4>对于文本节点的操作</h4><ol><li>获取文本节点上的文本，匹配其是否存在 双大括号( {{}} )语法，</li><li>通过 <strong>getVueVal</strong> 方法读取双大括号里面的值，</li><li>将双大括号的值作为监控项通过 **Watcher **监控(收集依赖)</li><li>当监控项值发生变化时(触发依赖)，通过<strong>回调函数</strong>将新值赋值到文本节点上</li></ol><p>到这里就实现了data中的数据值发生变化时同步更新界面上引用的数据</p><pre><code class=\"language-javascript\">import Watcher from \"../vue2ResponsivePrinciple/Watcher\";\nexport default class Compile{\n    constructor(el,vue) {\n        ...\n    }\n\n    node2Fragment(el){\n        ...\n    }\n\n    //编译\n    compile(el){\n        let childNodes = el.childNodes;\n        let self = this;\n        //捕获{{}}文本数据\n        let reg = /\\{\\{(.*)\\}\\}/;\n        childNodes.forEach(node=&gt;{\n            //获取节点的文本\n            let text = node.textContent;\n            //nodeType值为1，代表元素节点\n            if(node.nodeType == 1){\n                self.compileElement(node);\n            }else if(node.nodeType == 3 && reg.test(text)){\n                //nodeType值为3，代表文本节点\n                let name = text.match(reg)[1];\n                self.compileText(node,name);\n            }\n        })\n    }\n\n    compileElement(node){\n        ...\n    }\n\n    compileText(node,name){\n        //之前已经把data里面的数据循环遍历放到vue上了，所以可以传入vue\n        node.textContent = this.getVueVal(this.$vue,name);\n        //设置监控响应\n        new Watcher(this.$vue,name,(newValue)=&gt;{\n            node.textContent = newValue;\n        })\n    }\n\n    //获取使用的值a.b.n\n    getVueVal(vue,exp){\n        let val = vue;\n        exp = exp.split(\".\");\n        exp.forEach(key=&gt;{\n            val = val[key];\n        })\n        return val;\n    }\n}\n</code></pre><h4>对于元素节点的操作</h4><ol><li>获取元素节点的属性，如class、id、style、type等等，也包含自定义的属性v-model、v-if等等。</li><li>循环遍历节点上的属性，找出是否含有v-model属性。</li><li>获取到v-model属性上的值。如下，v-model的值就为a.b.n</li></ol><pre><code class=\"language-html\">&lt;input type=\"text\" v-model=\"a.b.n\"/&gt;\n</code></pre><ol><li>使用 Watcher 对 a.b.n &nbsp;进行监控，在回调函数中将新值赋值给元素节点的值。到这里就实现了Vue数据到界面视图的同步，即Vue中的数据进行变动时会将新值更新到界面上。</li><li>使用 getVueVal 获取a.b.n 对应的值，将值赋值给元素节点的值，实现绑定值的初始化</li><li>给元素节点设置addEventListener监听事件，触发事件时通过setVueVal方法将获取的新值赋值给监控项a.b.n对应的值。到这就实现了界面视图到Vue数据的同步，即界面的数据变动时，将变动值更新到Vue数据上。</li></ol><p>完整代码：</p><pre><code class=\"language-javascript\">import Watcher from \"../vue2ResponsivePrinciple/Watcher\";\nexport default class Compile{\n    constructor(el,vue) {\n        //vue实例\n        this.$vue = vue;\n        //挂载点\n        this.$el = document.querySelector(el);\n        if(this.$el){\n            // 调用函数，让节点变为fragment，类似于mustache中的tokens。实际上用的是AST，这里就是轻量级的，fragment\n            let $fragment = this.node2Fragment(this.$el);\n            //编译\n            this.compile($fragment);\n            //替换好的内容要上树\n            this.$el.appendChild($fragment);\n        }\n    }\n\n    node2Fragment(el){\n        /**\n         * 创造一个DocumentFragment类型节点，可以把它当作虚拟节点,消耗小\n         * 主要作用：充当其他要被添加到文档的节点的仓库，也就是充当初始父节点\n         * 其parentNode值为空\n         * @type {DocumentFragment}\n         */\n        let fragment = document.createDocumentFragment();\n        let child;\n        //获取文档节点中的第一个节点，并将其赋值给child\n        while(child = el.firstChild){\n            fragment.appendChild(child);\n        }\n        return fragment;\n    }\n\n    //编译\n    compile(el){\n        let childNodes = el.childNodes;\n        let self = this;\n\n        //捕获{{}}文本数据\n        let reg = /\\{\\{(.*)\\}\\}/;\n\n        childNodes.forEach(node=&gt;{\n            //获取节点的文本\n            let text = node.textContent;\n            //nodeType值为1，代表元素节点\n            if(node.nodeType == 1){\n                self.compileElement(node);\n            }else if(node.nodeType == 3 && reg.test(text)){\n                //nodeType值为3，代表文本节点\n                let name = text.match(reg)[1];\n                self.compileText(node,name);\n            }\n        })\n    }\n\n    compileElement(node){\n        //获取元素节点的属性，比如class,id等等。\n        let nodeAttrs = node.attributes;\n        //获取的nodeAttrs是一个类数组对象,将其转化为数组对象\n        let nodeAttrsArray = [...nodeAttrs];\n        let self = this;\n        nodeAttrsArray.forEach(attr=&gt;{\n            //在这里分析指令\n            let attrName = attr.name;\n            let value = attr.value;\n            //指令都是v-开头的，取字符串2位后字符\n            let dir = attrName.substring(2);\n            //判断是否为指令\n            if(attrName.indexOf(\'v-\') == 0){\n                //双向绑定\n                if(dir == \'model\'){\n                    // console.log(\'捕捉到v-model指令\',node);\n                    //将实际值放入v-model绑定的值\n                    //此时vue中的数据改变会影响界面的数据，数据从vue流向界面。\n                    new Watcher(self.$vue,value,value=&gt;{\n                        node.value = value;\n                    });\n                    //读取绑定的值\n                    let v = self.getVueVal(self.$vue,value);\n                    node.value = v;\n\n                    //添加界面数据变动影响vue里面的数据，通过给元素添加监听事件实现。\n                    node.addEventListener(\'input\',e=&gt;{\n                        let newVal = e.target.value;\n                        self.setVueVal(self.$vue,value,newVal);\n                        v = newVal;\n                    })\n                }\n            }\n        })\n    }\n\n    compileText(node,name){\n        //之前已经把data里面的数据循环遍历放到vue上了，所以可以传入vue\n        node.textContent = this.getVueVal(this.$vue,name);\n        //设置监控响应\n        new Watcher(this.$vue,name,(newValue)=&gt;{\n            node.textContent = newValue;\n        })\n    }\n\n    //获取使用的值a.b.n\n    getVueVal(vue,exp){\n        let val = vue;\n        exp = exp.split(\".\");\n        exp.forEach(key=&gt;{\n            val = val[key];\n        })\n        return val;\n    }\n\n    //修改值\n    setVueVal(vue,exp,value){\n        let val = vue;\n        exp = exp.split(\".\");\n        exp.forEach((key,i)=&gt;{\n            //获取最底层的值修改\n            if(i&lt; exp.length - 1){\n                val = val[key]\n            }else{\n                val[key] = value;\n            }\n        })\n    }\n}\n\n</code></pre><h2>index.js中引入测试</h2><p>通过webpack打包后的js文件中的方法和变量都会变成局部的，外部无法直接访问，因此可以将其添加到window上，方便外部访问。</p><pre><code class=\"language-javascript\">import Vue from \'./Vue\'\nwindow.Vue = Vue;\n</code></pre><h2>index.html主页测试</h2><p>这个index.html是初始模板，通过webpack打包后会使打包后的bundle.js文件自动的插入html模板文件中。</p><p>使用setTimeout是在JS文件加载解析后在进行实例化Vue，防止其为空。</p><pre><code class=\"language-html\">&lt;!DOCTYPE html&gt;\n&lt;html lang=\"en\"&gt;\n&lt;head&gt;\n    &lt;meta charset=\"UTF-8\"&gt;\n    &lt;title&gt;Title&lt;/title&gt;\n&lt;/head&gt;\n&lt;body&gt;\n    &lt;div id=\"app\"&gt;\n        {{a.b.n}}\n        &lt;h2 id=\"h2\" &gt;--------------------------------------&lt;/h2&gt;\n        &lt;input type=\"text\" v-model=\"a.b.n\"/&gt;\n    &lt;/div&gt;\n&lt;/body&gt;\n&lt;script&gt;\n    let vm = null;\n    setTimeout(()=&gt;{\n        vm = new Vue({\n            el:\"#app\",\n            data:{\n                a:{\n                    b:{\n                        n:10\n                    }\n                },\n                b:false,\n                c:55\n            },\n            watch:{\n                b:function(newValue,oldValue){\n                    console.log(newValue,oldValue)\n                }\n            }\n        });\n    },500);\n    console.log(vm);\n&lt;/script&gt;\n&lt;/html&gt;\n</code></pre><h2>测试结果</h2><p><img src=\"https://cdn.nlark.com/yuque/0/2023/png/35619076/1687748884245-95f95611-26e9-4050-a0dc-58f0996a3b7d.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p>最终实现了输入框和文本框同步，一个更改另一个数据也会同步更改。</p><h2>小结</h2><p>v-model如何实现数据双向绑定？</p><ol><li>先通过observe实现对Vue数据的监听。</li><li>通过Watcher监控v-model绑定项，并在其回调函数里面将新值更新到界面。实现了从Vue中的数据到界面的流动。</li><li>通过给监控的元素节点添加addEventListener事件来监听元素的改变，并在其回调函数里将界面最新值更新到Vue数据中。从而实现了数据从界面流向Vue数据。</li></ol>', 'vue', 'Vue3', 'success', '📝', 'linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%)', 1, 0, 0, 0, 0, '2026-07-01 21:27:23', '2026-07-01 21:27:23');
INSERT INTO sea_pack.`blog_project` VALUES (1, 'seapack-template', '基于 Vue 3 + TypeScript + Vite 构建的企业级后台管理模板，集成了权限管理、数据可视化、GIS 地图、金融数据监控等核心功能模块。\n\n', 'home', '#409eff', 'rgba(64,158,255,0.1)', 'https://github.com/seapack-hub/seapack-template', 0, 1, '2026-07-01 21:33:34', '2026-07-01 21:33:34');
INSERT INTO sea_pack.`blog_project` VALUES (2, 'SeaPackBackEnd', 'SeaPackBackEnd 是一个面向金融投资场景的后端服务平台，基于 Spring Boot 3 + MyBatis 构建。系统覆盖股票数据采集与解析、行情展示、股息率监控、基金持仓管理、AI 智能问答及完善的权限控制体系，提供 RESTful API 支撑前端 SPA 应用。', 'home', '#409eff', 'rgba(64,158,255,0.1)', 'https://github.com/seapack-hub/SeaPackBackEnd', 0, 1, '2026-07-01 21:35:41', '2026-07-01 21:35:41');
INSERT INTO sea_pack.`blog_project` VALUES (3, '文件相关功能', '文件相关功能开发', 'home', '#409eff', 'rgba(64,158,255,0.1)', 'https://github.com/seapack-hub/seapack-f-o', 0, 1, '2026-07-01 21:41:12', '2026-07-01 21:41:12');
